const baseDiscount = (amount, threshold) => {
  if (amount >= threshold) {
    if (threshold === 100) return 20;
    if (threshold === 200) return 50;
    if (threshold === 300) return 100;
  }
  return 0;
}

// 要求：实现高阶函数，接收两个参数：第一个为已柯里化阈值的基础折扣函数，第二个为额外规则函数，返回新的折扣计算函数
// 新函数接收订单金额、用户等级，返回总折扣（基础折扣+额外折扣）
const applyExtraRule = (extraRule, baseFunc) => (amount, level) => {
  const base = baseFunc(amount);
  const extra = extraRule(amount, level);
  return base + extra;
}

// 额外规则：VIP用户（等级为1）额外减免订单金额的5%，普通用户（等级为0）无额外折扣
